CREATE TABLE IF NOT EXISTS wards (id BIGINT NOT NULL AUTO_INCREMENT,name VARCHAR(150) NOT NULL,code VARCHAR(30) NOT NULL,floor INT NOT NULL,ward_type VARCHAR(50) NOT NULL,description VARCHAR(1000),status VARCHAR(20) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_wards_name(name),UNIQUE KEY uk_wards_code(code));
CREATE TABLE IF NOT EXISTS rooms (id BIGINT NOT NULL AUTO_INCREMENT,room_number VARCHAR(30) NOT NULL,ward_id BIGINT NOT NULL,room_type VARCHAR(50) NOT NULL,capacity INT NOT NULL,status VARCHAR(20) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_room_ward_number(ward_id,room_number),CONSTRAINT fk_rooms_ward FOREIGN KEY(ward_id) REFERENCES wards(id));
CREATE TABLE IF NOT EXISTS beds (id BIGINT NOT NULL AUTO_INCREMENT,bed_number VARCHAR(30) NOT NULL,ward_id BIGINT NOT NULL,room_id BIGINT NOT NULL,bed_type VARCHAR(50) NOT NULL,status VARCHAR(20) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_bed_room_number(room_id,bed_number),CONSTRAINT fk_beds_ward FOREIGN KEY(ward_id) REFERENCES wards(id),CONSTRAINT fk_beds_room FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE IF NOT EXISTS bed_allocations (id BIGINT NOT NULL AUTO_INCREMENT,patient_id BIGINT NOT NULL,bed_id BIGINT NOT NULL,admission_date DATE NOT NULL,discharge_date DATE NULL,notes VARCHAR(1000),PRIMARY KEY(id),CONSTRAINT fk_allocations_patient FOREIGN KEY(patient_id) REFERENCES patients(id),CONSTRAINT fk_allocations_bed FOREIGN KEY(bed_id) REFERENCES beds(id));
